//! Vectors for `wf_cut`/`wf_parts_of`/`wf_planes_of`/`wf_lines`, generated by
//! `scripts/cpp_vectors/frame_wf_lines_vectors.cpp`.

use std::collections::HashMap;

use fp_core::field::ext::F;
use fp_core::frame::parameters::GroupLine;
use fp_core::frame::wf_frame::{
    wf_cut, wf_lines, wf_parts_of, wf_planes_of, WfShape, WfShapeLookup,
};
use fp_core::iop::wf::{WfLookup, WfRun};

const VECTORS: &str = include_str!("../../fixtures/frame_wf_lines_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn runs_str(runs: &[WfRun]) -> String {
    runs.iter()
        .map(|r| format!("{}:{}:{}:{}", r.first_place, r.first_row, r.places, r.stride))
        .collect::<Vec<_>>()
        .join(";")
}

fn run_cut(name: &str, entries: &[WfRun], log_places: u32, log_rows_apart: u32, lines: &mut std::str::Lines) {
    let line = lines.next().unwrap();
    let kv = fields(line);
    assert_eq!(kv["name"], name);
    assert_eq!(kv["parts_of"], wf_parts_of(entries, log_places, log_rows_apart).to_string(), "{}: parts_of", name);
    let parts = wf_cut(entries, log_places, log_rows_apart);
    assert_eq!(kv["parts"], parts.len().to_string(), "{}: parts", name);
    assert_eq!(kv["planes"], wf_planes_of(&parts, 11).to_string(), "{}: planes", name);
    for (i, p) in parts.iter().enumerate() {
        let line = lines.next().unwrap();
        let pv = fields(line);
        assert_eq!(pv["i"], i.to_string());
        assert_eq!(pv["log_places"], p.log_places.to_string(), "{}: part {} log_places", name, i);
        assert_eq!(pv["runs"], runs_str(&p.runs), "{}: part {} runs", name, i);
    }
}

#[test]
fn wf_lines_match_the_cpp_reference() {
    let mut lines = VECTORS.lines();
    let two = vec![
        WfRun { first_place: 0, first_row: 0, places: 40, stride: 40 },
        WfRun { first_place: 0, first_row: 96, places: 2, stride: 2 },
    ];
    run_cut("two", &two, 6, 0, &mut lines);
    run_cut("two_apart", &two, 6, 1, &mut lines);
    run_cut("small_part", &two, 2, 0, &mut lines);
    run_cut("exact_part", &two, 5, 0, &mut lines);

    let lookup = WfLookup {
        name: String::from("look"),
        d: 8,
        mu: 0,
        live: 0,
        digit_weight: vec![F::one()],
        offset: F::from_u64(128),
        padding_key: F::zero(),
        parts: Vec::new(),
        first_bound: Vec::new(),
    };
    let shape = WfShape {
        k_col: 11,
        matrix_rows: 100,
        lookups: vec![WfShapeLookup { lookup, entries: two, log_rows_apart: 1 }],
    };
    for part_log in [11u32, 9, 6, 5, 4, 20, 63] {
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert_eq!(kv["part_log"], part_log.to_string());
        let l = wf_lines(&shape, &GroupLine::default(), part_log);
        let expected = line.split_once("fault=").unwrap().1.split(" lookups=").next().unwrap();
        assert_eq!(expected, l.fault.unwrap_or("-"), "part_log {}: fault", part_log);
        assert_eq!(kv["lookups"], l.lookups.len().to_string(), "part_log {}: lookups", part_log);
        for (i, x) in l.lookups.iter().enumerate() {
            let line = lines.next().unwrap();
            let xv = fields(line);
            assert_eq!(xv["name"], x.name);
            assert_eq!(xv["mu"], x.mu.to_string(), "part_log {}: mu", part_log);
            assert_eq!(xv["live"], x.live.to_string(), "part_log {}: live", part_log);
            assert_eq!(xv["parts"], x.parts.len().to_string(), "part_log {}: parts", part_log);
            for (j, p) in x.parts.iter().enumerate() {
                let line = lines.next().unwrap();
                let pv = fields(line);
                assert_eq!(pv["i"], j.to_string());
                assert_eq!(pv["log_places"], p.log_places.to_string());
                assert_eq!(pv["runs"], runs_str(&p.runs), "part_log {}: part {} runs", part_log, j);
            }
            let _ = i;
        }
    }
    assert!(lines.next().is_none(), "extra vector lines");
}
